impl Echo {
    /// Emits it as the event echoed (drained in order at the end of the phase).
    pub fn emit(&self, events: &mut crate::store::calls::Events) {
        events.emit(EVENT_ECHOED, Echo::WORDS, |row, heap| self.put(row, heap));
    }
}

